+      if (!res.ok) return;
+      const json = await res.json();
+      const data = json?.data;
+      if (!data) return;
+      if (data.settings) {
+        const s: AutoFavoriteSettings = { ...DEFAULTS, ...data.settings };
+        if (!loadedRef.current) {
+          setSettings(s);
+          setInitial(s);
+          loadedRef.current = true;
